// ===============================================================================
// DAEMIND SRE - PARSER DE OCORRÊNCIA DE TRANSPORTADORA
// ===============================================================================
const body = $json.body || $json;

const codigoRastreio = (body.codigo_rastreio || body.tracking_code || body.id || '').trim();
const statusOcorrencia = (body.status || body.event_name || body.descricao || 'Atraso Operacional').trim();
const transportadora = (body.transportadora || body.carrier || 'Correios').trim();
const detalhesLocal = body.local || body.cidade || 'Centro de Distribuição Local';

return [{
  json: {
    codigo_rastreio: codigoRastreio,
    status_ocorrencia: statusOcorrencia,
    transportadora: transportadora,
    detalhes_local: detalhesLocal
  }
}];
